import{_ as t,o as r,c as n,a5 as a}from"./chunks/framework.BjM_ivYE.js";const s="/RBQ/images/app/dashboard.pc.en.png",u=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/dashboard.md","filePath":"manual/gui/dashboard.md","lastUpdated":1790646319000}'),e={name:"manual/gui/dashboard.md"};function g(l,o,i,d,h,c){return r(),n("div",null,[...o[0]||(o[0]=[a('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>Open <strong>Dashboard</strong> with the <code>Dashboard</code> tile on the hub, which becomes active once the robot is connected. It lays the robot&#39;s live status out as cards, and in developer mode extra tabs add the robot state tables.</p><p><img src="'+s+'" alt="Dashboard summary"></p><h2 id="summary-cards" tabindex="-1">Summary cards <a class="header-anchor" href="#summary-cards" aria-label="Permalink to &quot;Summary cards&quot;">​</a></h2><h3 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h3><ul><li><strong>Robot S/N</strong> — the serial number of the robot you are looking at, at the very top of the card. It reads <code>—</code> while not connected, or when the robot runs older software.</li><li><strong>BATTERY</strong> — charge in % with the pack voltage and a status word: <ul><li><strong>Normal</strong></li><li><strong>Low</strong> — below 15 %</li><li><strong>Low voltage — charge now</strong> — below 10 % <em>and</em> pack voltage under 47 V. The numbers turn red. Stop work and charge.</li><li><strong>No signal</strong> — no battery data received (for example in simulation).</li></ul></li><li><strong>ROBOT HEALTH</strong> — <strong>IMU</strong>, <strong>CAN</strong>, <strong>FindPose</strong>, <strong>Control</strong>: each <strong>Normal</strong> or <strong>Check</strong>. The card badge reads <strong>OK</strong> when all are fine and <strong>Check</strong> otherwise.</li><li><strong>ROBOT PC</strong> — <strong>CPU</strong> load bar, <strong>Temp</strong>, <strong>MEM</strong> bar, and <strong>Throttle</strong> (<strong>Normal</strong> / <strong>Throttled</strong>).</li><li><strong>DISTANCE (TRIP)</strong> — <strong>Total</strong>, <strong>Trip A</strong>, <strong>Trip B</strong> in m, with <strong>Reset A</strong> / <strong>Reset B</strong> buttons.</li></ul><h3 id="joint·pose" tabindex="-1">Joint·Pose <a class="header-anchor" href="#joint·pose" aria-label="Permalink to &quot;Joint·Pose&quot;">​</a></h3><ul><li><strong>POSTURE</strong> — an artificial-horizon dial with <strong>Roll / Pitch / Yaw</strong> (only when the gyro widget is enabled in settings), <strong>GAIT_ID</strong>, <strong>Fall</strong> (<strong>Normal</strong> or <strong>FALL</strong>), <strong>RPY (°)</strong>, <strong>Height</strong> in m, and <strong>Battery A</strong> (pack current).</li><li>The badge shows the control-link state: <strong>LIVE</strong>, <strong>Connecting</strong>, or <strong>Disconnected</strong>.</li></ul><h3 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h3><ul><li><strong>PAYLOAD</strong> — <strong>Mounted slots</strong>, <strong>Total mass</strong>, and <strong>CoM X / Y / Z</strong>, followed by the attached gear, each <strong>Normal</strong> or <strong>Not detected</strong>: <strong>Robot arm</strong> and <strong>PTZ</strong>. RAPID-variant robots also list <strong>RCWS</strong>, <strong>RCGS</strong>, and <strong>CCTV</strong>.</li><li><strong>SENSOR</strong> — <strong>IMU</strong>, <strong>Front camera</strong>, <strong>Rear camera</strong>, <strong>Bottom camera 0</strong> – <strong>3</strong>, <strong>IR</strong>, <strong>Depth</strong>, and <strong>IR projector</strong>, each <strong>Normal</strong> or <strong>Not detected</strong>.</li></ul><p>A <strong>Radiation (KHNP)</strong> card appears only on KHNP-variant robots.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/manual/gui/developer-mode.html#dashboard">Developer mode</a>.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Warnings and errors that affect these values are collected in <a href="/RBQ/manual/gui/logs.html">Logs</a>.</li></ul>',14)])])}const b=t(e,[["render",g]]);export{u as __pageData,b as default};
